/** Colour base swatches: only roles may point at these (checked by npm run lint:tokens). */
export const baseColors = Object.freeze(["color-coral","color-cream","color-lavender","color-rose","color-peach","color-blush","color-mauve","color-sand","color-maroon","color-gold","color-amber","color-ink","color-paper","color-grey-900","color-grey-600","color-grey-300","color-grey-100","color-grey-200","color-grey-400","color-blue","color-grey-500","color-night","color-umber","color-soot","color-parchment"]);

/** token('color-cursor') → '#DE826D'. Throws on a typo so a wrong name can't fall back silently. */
export function token(name, mode = "light") {
  if (!(name in tokens)) throw new Error(`Unknown design token: ${name}`);
  return mode === "dark" && name in darkTokens ? darkTokens[name] : tokens[name];
}
